-- Approved made-to-order offer: 600 TL per card. Preserve archived, custom and already priced records.
UPDATE shop_card_themes SET data_json = json_set(data_json, '$.priceMinor', 60000, '$.available', json('true'), '$.madeToOrder', json('true')), updated_at = datetime('now') WHERE id = 'oliva-bistro' AND json_extract(data_json, '$.status') = 'demo' AND json_extract(data_json, '$.priceMinor') IS NULL AND json_extract(data_json, '$.front') IN ('/shop/artwork/demo-oliva-bistro-front.svg', '/shop/artwork/demo-oliva-bistro-pair.png');
